"""Owner-approved consultation fields; same existing email integration and visual classes."""
from html import escape
NOTICE='Visits to your hotel, home, office or other location are subject to availability, service suitability and confirmation. Additional travel or mobile-service charges may apply. Any applicable charges will be communicated for your approval before the visit is confirmed.'
def input_(id,label,name,type='text',required=False,extra=''):
 return '<div><label for="'+id+'">'+label+(' (required)' if required else ' (optional)')+'</label><input id="'+id+'" name="'+name+'" type="'+type+'" '+('required ' if required else '')+extra+'></div>'
def select(id,label,name,options,required=True):
 return '<div><label for="'+id+'">'+label+(' (required)' if required else ' (optional)')+'</label><select id="'+id+'" name="'+name+'"'+(' required' if required else '')+'><option value="">Select an option</option>'+''.join('<option value="'+escape(value,quote=True)+'">'+escape(text)+'</option>' for value,text in options)+'</select></div>'
def fields():
 body='<div class="request-fields">'+input_('requestName','Full name','Full Name',required=True,extra='autocomplete="name" maxlength="160"')+input_('requestPhone','Phone / WhatsApp','Phone Number','tel',True,'autocomplete="tel" inputmode="tel" maxlength="40"')+input_('requestEmail','Email address','Email Address','email',extra='autocomplete="email" maxlength="254"')+'</div>'
 body+=select('consultationMethod','Where would you prefer your consultation?','Consultation Method',[('workshop',"I will visit Mr Sewing Fashion's workshop."),('visit','I would like Mr Sewing Fashion to visit my location.'),('phone','I prefer an initial phone / WhatsApp consultation.')])
 body+='<fieldset id="consultationVisit" hidden disabled><legend>Consultation at your location</legend>'+select('consultationLocationType','Location type','Location Type',[(x,x) for x in ['Hotel','Home','Office or Workplace','Other']])+input_('consultationBuilding','Hotel, building or location name','Location Name',extra='maxlength="200"')+input_('consultationAddress','Area or address','Area or Address',required=True,extra='maxlength="300" autocomplete="street-address"')+input_('consultationDirections','Additional directions','Additional Directions',extra='maxlength="500"')+'<aside aria-labelledby="mobile-consultation-title"><h3 id="mobile-consultation-title">Mobile Consultation Notice</h3><p>'+NOTICE+'</p></aside></fieldset>'
 body+='<div class="request-fields">'+input_('requestDate','Preferred consultation date','Preferred Consultation Date','date',True,'aria-describedby="consultationSchedule"')+input_('requestTime','Preferred consultation time (Kigali time)','Preferred Consultation Time','time',True,'step="60" aria-describedby="consultationSchedule"')+'</div><p id="consultationSchedule" role="status">Choose a date to see the applicable business-hours guidance. A request is not a confirmed appointment.</p>'
 body+='<fieldset data-consultation-service="custom-tailoring" hidden disabled><legend>Custom Tailoring &amp; Suits</legend>'+select('consultationTailoringGarment','Garment type','Garment Type',[(x,x) for x in ["Men’s Suit","Women’s Suit","Other Clothing"]])+select('consultationDesign','Do you already have a design or photograph?','Design or Photograph',[(x,x) for x in ['Yes','No','Not sure yet']])+'<div id="consultationPictures" hidden><button type="button" class="home-button home-button-gold" id="consultationSharePictures">Share Design Pictures on WhatsApp (optional)</button><p>Attach your pictures and press Send in WhatsApp. They are not uploaded or sent automatically.</p></div></fieldset>'
 body+='<fieldset data-consultation-service="alterations" hidden disabled><legend>Clothing Alterations &amp; Repairs</legend>'+input_('consultationRepairGarment','Garment type','Garment Type',required=True,extra='maxlength="160"')+input_('consultationRepairInfo','Additional garment information','Garment Information',extra='maxlength="400"')+'<p>Garment inspection may be required before suitability and pricing can be confirmed.</p></fieldset>'
 body+='<fieldset data-consultation-service="garment-care" hidden disabled><legend>Garment Care &amp; Cleaning</legend>'+select('consultationCareGarment','Garment type','Garment Type',[(x,x) for x in ["Men’s Suits","Women’s Suits","Other Clothing"]])+input_('consultationQuantity','Number of garments','Quantity','number',True,'min="1" step="1"')+input_('consultationCondition','Garment condition or concerns','Garment Condition',extra='maxlength="500"')+'<p>Suitability and acceptance depend on the garment and the care required. Our team will assess your request.</p></fieldset>'
 body+='<div><label id="consultationRequirementsLabel" for="requestMessage">Service-specific requirements (required)</label><textarea id="requestMessage" name="Consultation Requirements" rows="4" maxlength="4000" required></textarea></div><div><label for="requestAdditional">Additional information (optional)</label><textarea id="requestAdditional" name="Additional Information" rows="3" maxlength="1000"></textarea></div>'
 return body
